import{_ as a,o as e,c as s,a2 as r}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"What is OrbySystems?","description":"","frontmatter":{"title":"What is OrbySystems?"},"headers":[],"relativePath":"docs/overview/what-is-orby.md","filePath":"docs/overview/what-is-orby.md","lastUpdated":1790284433000}'),o={name:"docs/overview/what-is-orby.md"};function i(n,t,l,d,c,h){return e(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="what-is-orbysystems" tabindex="-1">What is OrbySystems? <a class="header-anchor" href="#what-is-orbysystems" aria-label="Permalink to &quot;What is OrbySystems?&quot;">​</a></h1><p>OrbySystems is a personal AI agent focused on privacy. You chat with it in plain language, and it can work over your own documents and data — answering questions, finding things, and building on what it learns about your situation over time.</p><p>OrbySystems&#39;s focus is personal finance: point it at your bank statements, brokerage exports, and manually-tracked assets, and it becomes a private financial assistant — categorizing transactions, tracking net worth, and answering questions like &quot;how much did I spend on groceries last month?&quot; directly from your real data.</p><p>OrbySystems can also chat over general documents, with the same privacy-first approach underneath.</p><h3 id="local-first" tabindex="-1">Local first <a class="header-anchor" href="#local-first" aria-label="Permalink to &quot;Local first&quot;">​</a></h3><p>OrbySystems keeps all your data local - no data in the cloud, no data sent to an external LLM unless you explicity decide it. Because your data stays local, it can never be used to train third-party LLMs, and it can never be exposed by an external provider&#39;s data breach or leak. OrbySystems is for people who don&#39;t want to take chances with their <a href="./how-orby-is-different">personal data</a>.</p><h2 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where to start&quot;">​</a></h2><ul><li>New to OrbySystems? Walk through <a href="/docs/getting-started/install-orby">Getting Started</a> to install it and create your first project.</li><li>Curious what it&#39;s capable of? See <a href="/docs/overview/what-can-orby-do">What can OrbySystems do?</a>.</li><li>Want to know what sets it apart? See <a href="/docs/overview/how-orby-is-different">How OrbySystems is different</a>.</li></ul>',8)])])}const p=a(o,[["render",i]]);export{u as __pageData,p as default};
